#!/usr/bin/env node
/**
 * Exported games and the studio preview run the same renderer and story rules as the studio.
 * Both bundles are generated here; never edit the generated files directly.
 */
import { build } from "esbuild";
import { readFile, writeFile, unlink } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
async function bundle(entry, globalName) {
  const result = await build({
    entryPoints: [path.join(root, entry)],
    write: false,
    bundle: true,
    minify: true,
    format: "iife",
    ...(globalName ? { globalName } : {}),
    platform: "browser",
    target: ["es2022"],
    legalComments: "inline",
  });
  return result.outputFiles[0].text;
}
const outputs = [
  {
    entry: "src/animation/controller.ts",
    globalName: "FrameAnimation",
    file: "src/animation/player-runtime.generated.ts",
    name: "PORTRAIT_RUNTIME_SOURCE",
    note: "edit controller.ts and runtime modules",
  },
  {
    entry: "src/player/runtime.ts",
    file: "src/player/player-runtime.generated.ts",
    name: "PLAYER_RUNTIME_SOURCE",
    note: "edit src/player/runtime.ts and the engine",
  },
];
for (const output of outputs)
  await writeFile(
    path.join(root, output.file),
    `// Generated by scripts/build-player-runtime.mjs; ${output.note}.\n` +
      `export const ${output.name}: string = ${JSON.stringify(await bundle(output.entry, output.globalName))};\n`,
  );
// The storybook fonts (SIL OFL, see src/player/fonts/) as embeddable @font-face rules. Exported
// players include them only when a project uses them.
const LATIN =
  "U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD";
const faces = [
  ["Cormorant Garamond", "normal", "300 700", "cormorant-garamond-latin.woff2"],
  ["Cormorant Garamond", "italic", "300 700", "cormorant-garamond-italic-latin.woff2"],
  ["Cinzel", "normal", "600", "cinzel-600-latin.woff2"],
];
let fontCss = "";
for (const [family, style, weight, file] of faces) {
  const data = (await readFile(path.join(root, "src/player/fonts", file))).toString("base64");
  fontCss += `@font-face{font-family:"${family}";font-style:${style};font-weight:${weight};font-display:block;src:url(data:font/woff2;base64,${data}) format("woff2");unicode-range:${LATIN}}`;
}
await writeFile(
  path.join(root, "src/player/fonts.generated.ts"),
  "// Generated by scripts/build-player-runtime.mjs from src/player/fonts/; do not edit.\n" +
    `export const STORYBOOK_FONT_FACES: string = ${JSON.stringify(fontCss)};\n`,
);
const runtimeLicense = await readFile(path.join(root, "LICENSE"), "utf8");
const fontLicenses = await Promise.all(
  ["OFL-Cinzel.txt", "OFL-CormorantGaramond.txt"].map(async (file) =>
    `${file}\n${await readFile(path.join(root, "src/player/fonts", file), "utf8")}`,
  ),
);
await writeFile(
  path.join(root, "src/player/licenses.generated.ts"),
  "// Generated by scripts/build-player-runtime.mjs from license sources; do not edit.\n" +
    `export const RUNTIME_LICENSE: string = ${JSON.stringify(runtimeLicense)};\n` +
    `export const STORYBOOK_FONT_LICENSES: string = ${JSON.stringify(fontLicenses.join("\n\n"))};\n`,
);
await unlink(
  path.join(root, "src/animation/player-runtime.generated.js"),
).catch((error) => {
  if (error.code !== "ENOENT") throw error;
});
console.log("Built portable portrait and story player runtimes.");
